001: import http from 'node:http';
002: import dns from 'node:dns/promises';
003: 
004: const targetHost = '127.0.0.1';
005: const targetPort = 7331;
006: const listenPort = 7443;
007: const normalize = value => (value || '').replace(/^::ffff:/, '').toLowerCase();
008: const trusted = new Set(['127.0.0.1', '::1']);
009: 
010: async function refreshTrusted() {
011:   for (const host of ['heaven2', 'heaven2.myfiosgateway.com']) {
012:     try {
013:       const rows = await dns.lookup(host, { all: true, verbatim: true });
014:       for (const row of rows) trusted.add(normalize(row.address));
015:     } catch {}
016:   }
017: }
018: 
019: await refreshTrusted();
020: setInterval(refreshTrusted, 60000).unref();
021: 
022: const server = http.createServer(async (req, res) => {
023:   const remote = normalize(req.socket.remoteAddress);
024:   if (!trusted.has(remote)) {
025:     await refreshTrusted();
026:     if (!trusted.has(remote)) {
027:       res.writeHead(403, { 'Content-Type': 'text/plain' });
028:       res.end('Forbidden: LAN peer not trusted');
029:       return;
030:     }
031:   }
032:   if (req.url === '/health') {
033:     res.writeHead(200, { 'Content-Type': 'application/json' });
034:     res.end(JSON.stringify({ ok: true, peer: remote, target: targetPort }));
035:     return;
036:   }
037:   const headers = { ...req.headers, host: `${targetHost}:${targetPort}` };
038:   const proxy = http.request({
039:     host: targetHost,
040:     port: targetPort,
041:     path: req.url,
042:     method: req.method,
043:     headers
044:   }, upstream => {
045:     res.writeHead(upstream.statusCode || 502, upstream.headers);
046:     upstream.pipe(res);
047:   });
048:   proxy.on('error', err => {
049:     res.writeHead(502, { 'Content-Type': 'text/plain' });
050:     res.end(err.message);
051:   });
052:   req.pipe(proxy);
053: });
054: 
055: server.listen({ port: listenPort, host: '::', ipv6Only: false }, () => {
056:   console.log(`Heaven LAN control proxy listening on [::]:${listenPort}; backend 127.0.0.1:${targetPort}`);
057: });
